import{_ as t,c as a,o,a2 as s}from"./chunks/framework.QTfwLiL8.js";const u=JSON.parse('{"title":"0022 Improved Shootstate Usage","description":"","frontmatter":{"github_repo":"https://github.com/gardener/enhancements","github_subdir":"geps/0022-improved-shootstate-usage","params":{"github_branch":"main"},"path_base_for_github_subdir":{"from":"content/docs/proposals/0022-improved-shootstate-usage/README.md","to":"README.md"},"title":"0022 Improved Shootstate Usage","prev":false,"next":false},"headers":[],"relativePath":"docs/proposals/0022-improved-shootstate-usage/_index.md","filePath":"docs/proposals/0022-improved-shootstate-usage/_index.md","lastUpdated":null}'),r={name:"docs/proposals/0022-improved-shootstate-usage/_index.md"};function i(n,e,l,d,c,h){return o(),a("div",null,e[0]||(e[0]=[s(`<h1 id="gep-0022-improved-usage-of-the-shootstate-api" tabindex="-1">GEP-0022: Improved Usage of the <code>ShootState</code> API <a class="header-anchor" href="#gep-0022-improved-usage-of-the-shootstate-api" aria-label="Permalink to &quot;GEP-0022: Improved Usage of the \`ShootState\` API&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="/docs/proposals/0022-improved-shootstate-usage/readme/#gep-0022-improved-usage-of-the-shootstate-api">GEP-0022: Improved Usage of the <code>ShootState</code> API</a><ul><li><a href="/docs/proposals/0022-improved-shootstate-usage/readme/#table-of-contents">Table of Contents</a></li><li><a href="/docs/proposals/0022-improved-shootstate-usage/readme/#summary">Summary</a></li><li><a href="/docs/proposals/0022-improved-shootstate-usage/readme/#motivation">Motivation</a><ul><li><a href="/docs/proposals/0022-improved-shootstate-usage/readme/#goals">Goals</a></li><li><a href="/docs/proposals/0022-improved-shootstate-usage/readme/#non-goals">Non-Goals</a></li></ul></li><li><a href="/docs/proposals/0022-improved-shootstate-usage/readme/#proposal">Proposal</a></li><li><a href="/docs/proposals/0022-improved-shootstate-usage/readme/#alternatives">Alternatives</a></li><li><a href="/docs/proposals/0022-improved-shootstate-usage/readme/#future-improvements">Future Improvements</a><ul><li><a href="/docs/proposals/0022-improved-shootstate-usage/readme/#eliminating-the-worker-state-reconciler">Eliminating the <code>Worker</code> State Reconciler</a></li><li><a href="/docs/proposals/0022-improved-shootstate-usage/readme/#compressing-the-shootstate-data">Compressing the <code>ShootState</code> Data</a></li></ul></li></ul></li></ul><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>For each <code>Shoot</code> resource, <code>gardenlet</code> creates a corresponding <code>ShootState</code> resource which has the same lifecycle as the <code>Shoot</code>. Today, such resources are used for two purposes:</p><ol><li>Exposing the client CA certificate and key of the shoot cluster such that the <code>gardener-apiserver</code> is able to issue short-lived client certificates via the <a href="https://github.com/gardener/gardener/tree/master/docs/usage/shoot/shoot_access.md#shootsadminkubeconfig-subresource" target="_blank" rel="noreferrer"><code>shoots/adminkubeconfig</code> subresource</a>.</li><li>Storing the most crucial data for shoot clusters which is necessary to migrate and restore a cluster from one <code>Seed</code> to another (certificates, keys, secrets, relevant extensions state for created infrastructure or worker machines).</li></ol><p>Especially due to the second purpose, the <code>ShootState</code> API imposes several scalability concerns and limitations for large Gardener installations. Hence, this GEP proposes the elimination of said <code>ShootState</code> API by replacing it with lightweight alternatives.</p><p>This GEP focuses on the second use-case only and ignores the first use-case. An alternative for it is worked on separately in <a href="https://github.com/gardener/gardener/issues/7999" target="_blank" rel="noreferrer">Introduce <code>core.gardener.cloud/v1beta1.InternalSecret</code> API #7999</a>.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>The <code>gardenlet</code> runs <a href="https://github.com/gardener/gardener/tree/master/docs/concepts/gardenlet.md#shootstate-controller" target="_blank" rel="noreferrer">two controllers</a> for maintaining the most crucial data of shoot clusters in their <code>ShootState</code> resources:</p><ul><li><p>The <a href="https://github.com/gardener/gardener/tree/master/pkg/gardenlet/controller/shootstate/secret" target="_blank" rel="noreferrer"><code>shootstate-secret</code></a> controller watches <code>Secret</code>s labeled with <code>persist=true</code> in the shoot namespaces in the seed cluster. It persists all labels and data of such <code>Secret</code>s into the related <code>ShootState</code> resource.</p><p>In reality, those <code>Secret</code>s only change when the end-user initiates a credentials rotation operation, so rather rarely. Still, duplicating all labels and data of such <code>Secret</code>s into the garden cluster increases the size of <code>ShootState</code> resources.</p></li><li><p>The <a href="https://github.com/gardener/gardener/tree/master/pkg/gardenlet/controller/shootstate/extensions" target="_blank" rel="noreferrer"><code>shootstate-extensions</code></a> controller watches all resources of the <code>extensions.gardener.cloud/v1alpha1</code> API group in the shoot namespaces in the seed cluster. It persists all extensions state and resources in the respective <code>.status.state</code> and <code>.status.resources</code> fields. See also <a href="https://github.com/gardener/gardener/tree/master/docs/extensions/migration.md" target="_blank" rel="noreferrer">this document</a> for more background information.</p><p>In reality, this is the controller which can cause quite a lot of network I/O (hence, traffic and costs). While most of the extension states change rather rarely, the state of the <code>extensions.gardener.cloud/v1alpha1.Worker</code> resources can update quite frequently whenever new worker machines join or leave the cluster. <code>gardenlet</code> has to watch and replicate all such state changes to the <code>ShootState</code> resource.</p></li></ul><p>In large Gardener installations, this can result in a lot of requests to the <code>gardener-apiserver</code> (transitively, also to ETCD of the garden cluster), and it can significantly contribute to the ETCD size (note that ETCD has a practical space limit of 8 GB). Besides, it increases the memory consumption considerably for all clients working with <code>ShootState</code>s.</p><p><code>ShootState</code>s were introduced years ago when control plane migration was still in its early phase. Back then, we wanted to achieve so-called &quot;bad case control plane migrations&quot; (which practically means restoring a shoot control plane without being able to access its current seed cluster (maybe because it&#39;s down or destroyed)). For such scenarios, it is obviously necessary to have to most up-to-date state available in order to perform the restoration in a new seed cluster. As the current seed cluster is unavailable in this scenario and cannot be accessed, we decided to continuously replicate the state to the garden cluster.</p><p>With <a href="https://github.com/gardener/gardener/issues/6302" target="_blank" rel="noreferrer">Finalise &quot;Bad Case&quot; Control Plane Migration #6302</a>, however, this use case has been eliminated. It was decided that it won&#39;t be implemented, especially after <a href="https://github.com/gardener/gardener/issues/6529" target="_blank" rel="noreferrer">☂️ [GEP-20] Highly Available Seed and Shoot Clusters #6529</a> brings the ability to run seed clusters in a highly available manner (which reduces the chances to ever need a &quot;bad case control plane migration&quot; even further). With this, it is no longer necessary to continuously replicate the relevant state to the garden cluster, allowing us to reduce the usage of the <code>ShootState</code> API.</p><h3 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h3><ul><li>Reduce network traffic and resulting costs due to continuous replication of state from seed clusters to garden clusters.</li><li>Reduce size of garden cluster&#39;s ETCD, and with it the risk to run into its practical space limit of 8 GB.</li><li>Simplify code that was mainly introduced in the context of the &quot;bad case control plane migration&quot;.</li><li>Perform regular backups of the shoot states for shoots running on unmanaged seeds.</li></ul><h3 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h3><ul><li>Adaptation of the <a href="/docs/proposals/0022-improved-shootstate-usage/readme/#summary">&quot;first use-case&quot;</a> of the <code>ShootState</code> API (this is handled separately in <a href="https://github.com/gardener/gardener/issues/7999" target="_blank" rel="noreferrer">Introduce <code>core.gardener.cloud/v1beta1.InternalSecret</code> API #7999</a>).</li><li>Provide means to restore a deleted <code>Shoot</code> from its persisted state.</li></ul><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><p>Now that the &quot;bad case control plane migration&quot; scenario has been eliminated, the sole usage of the <code>ShootState</code> resource is for the &quot;good case control plane migration&quot;. However, this case is significantly simpler since the current seed cluster is still available. Hence, when a control plane migration is triggered, <code>gardenlet</code> could easily collect the needed data from the current seed cluster, store it in the garden cluster for later usage during the restoration phase, and eventually delete the data again.</p><p>We are proposing the following changes:</p><ol><li>The <a href="https://github.com/gardener/gardener/tree/master/pkg/gardenlet/controller/shootstate/extensions" target="_blank" rel="noreferrer"><code>shootstate-extensions</code></a> controller of <code>gardenlet</code> will be dropped, i.e., it will no longer replicate the extensions states to the <code>ShootState</code> resources in the garden cluster.</li><li>The <a href="https://github.com/gardener/gardener/tree/master/pkg/gardenlet/controller/shootstate/secret" target="_blank" rel="noreferrer"><code>shootstate-secret</code></a> controller will also be dropped as soon as <a href="https://github.com/gardener/gardener/issues/7999" target="_blank" rel="noreferrer">Introduce <code>core.gardener.cloud/v1beta1.InternalSecret</code> API #7999</a> has been implemented.</li></ol><p>With this, the usage of the <code>ShootState</code> API can be drastically reduced.</p><ol start="3"><li><p>During the <code>Migrate</code> phase of a <code>Shoot</code>, <code>gardenlet</code> will fetch all relevant state in the shoot namespaces of the current seed, similar to what the two controllers are doing as of today:</p><ol><li>all labels and data for <code>Secret</code>s labeled with <code>persist=true</code>.</li><li>all <code>.status.state</code> and <code>.status.resources</code> for resources in the <code>extensions.gardener.cloud/v1alpha1</code> API group.</li></ol><p>The <code>gardenlet</code> puts this state into regular <code>core.gardener.cloud/v1beta1.ShootState</code> resource stored in the namespace of the respective <code>Shoot</code> in the garden cluster.</p></li><li><p>During the <code>Restore</code> phase of a <code>Shoot</code>, <code>gardenlet</code> will read the created <code>core.gardener.cloud/v1beta1.ShootState</code> from the namespace of the respective <code>Shoot</code> in the garden cluster and uses it to populate the state in the new seed cluster just like today.</p></li><li><p>After successful restoration, the created <code>core.gardener.cloud/v1beta1.ShootState</code> is deleted again from the namespace of the respective <code>Shoot</code> in the garden cluster.</p></li></ol><p>This approach addresses all the concerns and downsides of today&#39;s implementation: Control plane migrations happen rather rarely and usually only take a few minutes. The shoot state is still replicated to the garden cluster during this process, however it will no longer exist for the entire lifetime of the <code>Shoot</code> but only during the short period of the control plane migration (which in reality is actually never executed for most <code>Shoot</code>s). It will also not be continuously updated anymore. Only when a migration is performed, the current state is collected, and deleted again after the migration has been completed.</p><blockquote><p>⚠️There will be one exception to the above which applies for <code>Shoot</code>s running on so-called &quot;unmanaged <code>Seed</code>s&quot;. Such <code>Seed</code>s are those not backed by a <code>seedmanagement.gardener.cloud/v1alpha1.ManagedSeed</code> object.</p><p>For <code>Shoot</code>s running on such unmanaged <code>Seed</code>s, we cannot make any assumptions about the ETCD backups. While we can easily access the ETCD backup of a <code>ManagedSeed</code> in case of a disaster in order to get access to the relevant state of a particular <code>Shoot</code>, we can&#39;t do so for unmanaged <code>Seed</code>s.</p><p>Hence, we propose to run a periodic job that backs up the shoot state for <code>Shoot</code>s running on unmanaged <code>Seed</code>s. This periodic job will be implemented as part of a new controller in <code>gardenlet</code> which runs according to the configured period (default: <code>6h</code>).</p></blockquote><p>In summary:</p><ul><li>the size of the ETCD of the garden cluster will be drastically reduced, especially for large Gardener installations.</li><li>the load on the API server and ETCD of the garden cluster will be drastically reduced, preparing the components for further scale.</li><li>the network traffic and related costs will be drastically reduced.</li><li>only very few <code>ShootState</code>s will remain (and those get updated less frequently), since productive Gardener landscapes typically don&#39;t run a lot of <code>Shoot</code>s on unmanaged <code>Seed</code>s.</li></ul><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to &quot;Alternatives&quot;">​</a></h2><p>Instead of persisting the shoot state via the <code>core.gardener.cloud/v1beta1.ShootState</code> resource into ETCD of the garden cluster, the relevant data could be pushed into the backup buckets that already exist as of today and are used for the ETCD backups.</p><p>We have implemented a <a href="https://github.com/rfranzke/gardener/commits/hackathon/shootstate-s3" target="_blank" rel="noreferrer">PoC</a> during the <a href="https://github.com/gardener-community/hackathon/tree/main/2023-05_Leverkusen" target="_blank" rel="noreferrer">Hack the Garden 05/2023 hackathon</a> which extends the <code>extensions.gardener.cloud/v1alpha1</code> API with two new resources:</p><ul><li><p><code>BackupUpload</code>s, which can be used to upload arbitrary data to an existing <code>BackupEntry</code>.</p><details><summary>Example YAML manifest</summary><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">apiVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">extensions.gardener.cloud/v1alpha1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">BackupUpload</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">metadata</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">example</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  namespace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">default</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  entryName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">example-entry</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  filePath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">shootstate.yaml.enc</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">local</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;to-be-uploaded-data&gt;</span></span></code></pre></div></details></li><li><p><code>BackupDownload</code>s, which can be used to download arbitrary data from an existing <code>BackupEntry</code>.</p><details><summary>Example YAML manifest</summary><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">apiVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">extensions.gardener.cloud/v1alpha1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">BackupDownload</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">metadata</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">example</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  namespace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">default</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  entryName</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">example-entry</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  filePath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">shootstate.yaml.enc</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">local</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">status</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&lt;downloaded-data&gt;</span></span></code></pre></div></details></li></ul><p>Similar to all other resources in the <code>extensions.gardener.cloud/v1alpha1</code> API, we could provide respective controllers in the <a href="https://github.com/gardener/gardener/tree/master/docs/extensions" target="_blank" rel="noreferrer">extensions library</a> such that provider extensions only need to implement their specific business logic (i.e., uploading/downloading to/from their infrastructure-specific object storage).</p><p>However, this approach is significantly more expensive in terms of development costs and complexity since the following additional adaptations would be required:</p><ul><li>Introduction of new resources in the <code>extensions.gardener.cloud/v1alpha1</code> API which comes with validation, deployment dependencies, etc.</li><li>Introduction of new extension controllers.</li><li>Adaptation of all existing provider extensions with support for <code>Backup{Bucket,Entry}</code>s with the implementation for the new <code>Backup{Up,Down}load</code> resources.</li><li>Encryption of the shoot state data (since we do not want to store it as plain text in the backup buckets). With above proposal, encryption is handled by <code>gardener-apiserver</code> via the standard <code>EncryptionConfiguration</code>.</li><li>Management (incl. rotation) of a respective encryption key.</li></ul><p>So far, the only justification for following such a path would be the necessity for regular backups of the shoot states (e.g., every hour or so). In this case, the shoot states would again be stored in the garden cluster for the entire lifetime of the <code>Shoot</code>s.</p><p>This alternative approach would still improve a few things like network traffic, etc. since the data would no longer be continuously replicated (only with a much lower frequency compared to today), but eventually today&#39;s technical debts remain limiting the garden cluster&#39;s scalability. As no appropriate reasoning for regular backups has been presented yet, they were added as &quot;non-goal&quot; in this GEP. Hence, implementing this alternative approach is considered unnecessary.</p><h2 id="future-improvements" tabindex="-1">Future Improvements <a class="header-anchor" href="#future-improvements" aria-label="Permalink to &quot;Future Improvements&quot;">​</a></h2><h3 id="eliminating-the-worker-state-reconciler" tabindex="-1">Eliminating the <code>Worker</code> State Reconciler <a class="header-anchor" href="#eliminating-the-worker-state-reconciler" aria-label="Permalink to &quot;Eliminating the \`Worker\` State Reconciler&quot;">​</a></h3><p>With <a href="https://github.com/gardener/gardener/issues/7594" target="_blank" rel="noreferrer">Move <code>machine-controller-manager</code> reconciliation responsibility from extensions to <code>gardenlet</code> #7594</a>, <code>gardenlet</code> will become aware of the <code>machine.sapcloud.io/v1alpha1</code> API used for managing the worker machines of shoot clusters.</p><p>This allows to drop the <a href="https://github.com/gardener/gardener/tree/master/docs/extensions/pkg/controller/worker/reconciler.go" target="_blank" rel="noreferrer"><code>Worker</code> state reconciler</a> which currently watches all <code>MachineDeployment</code>s, <code>MachineSet</code>s, and <code>Machine</code>s, and replicates their specifications into the <code>.status.state</code> of the related <code>extensions.gardener.cloud/v1alpha1.Worker</code> resource. Instead, <code>gardenlet</code> could then collect these resources during the <code>Migrate</code> phase itself, effectively compute the necessary <code>Worker</code> state, and also restore it during the <code>Restore</code> phase.</p><p>With this approach, we could also reduce the load on the seed clusters&#39; API servers since it would no longer be necessary to continuously duplicate the machine-related resources into the <code>Worker</code> status. For now, this GEP focuses on the <code>ShootState</code> API only, but as soon as <a href="https://github.com/gardener/gardener/issues/7594" target="_blank" rel="noreferrer">Move <code>machine-controller-manager</code> reconciliation responsibility from extensions to <code>gardenlet</code> #7594</a> has been implemented, we could start looking into this next-step improvement.</p><h3 id="compressing-the-shootstate-data" tabindex="-1">Compressing the <code>ShootState</code> Data <a class="header-anchor" href="#compressing-the-shootstate-data" aria-label="Permalink to &quot;Compressing the \`ShootState\` Data&quot;">​</a></h3><p>Typically, the size of a <code>ShootState</code> resource is dominated by the <code>MachineDeployment</code>s, <code>MachineSet</code>s, and <code>Machine</code>s. In case the few remaining <code>ShootState</code> resources still grow too large, one could implement compression strategies for the machine state (and maybe other state as well, if necessary) to reduce the overall storage size.</p><p>Since we expect only a very small number of <code>ShootState</code>s to remain for productive Gardener installations, this optimization is out of scope for now.</p>`,45)]))}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
